package main

import (
	"net/http"
	"net/http/httptest"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

func trustCreateFile(t *testing.T, dir, name string) {
	t.Helper()
	if err := os.WriteFile(filepath.Join(dir, name), []byte("content"), 0644); err != nil {
		t.Fatalf("failed to create file %s: %v", name, err)
	}
}

func trustCreateDir(t *testing.T, dir, name string) {
	t.Helper()
	if err := os.MkdirAll(filepath.Join(dir, name), 0755); err != nil {
		t.Fatalf("failed to create dir %s: %v", name, err)
	}
}

func trustBrowseRequest(t *testing.T, mux *http.ServeMux, path, sort, order string) *httptest.ResponseRecorder {
	t.Helper()
	url := "/api/browse?path=" + path
	if sort != "" {
		url += "&sort=" + sort
	}
	if order != "" {
		url += "&order=" + order
	}
	req := httptest.NewRequest(http.MethodGet, url, nil)
	rr := httptest.NewRecorder()
	mux.ServeHTTP(rr, req)
	return rr
}

func trustEntryNames(resp BrowseResponse) []string {
	names := make([]string, 0, len(resp.Entries))
	for _, e := range resp.Entries {
		names = append(names, e.Name)
	}
	return names
}

func TestTrust_SortBySizeDescLargestFileFirstAfterFolders(t *testing.T) {
	root := setupTestDir(t)
	trustCreateFile(t, root, "small.txt")
	trustCreateFile(t, root, "large.txt")
	trustCreateDir(t, root, "afolder")

	mux := newMux(testConfig(root))
	rr := trustBrowseRequest(t, mux, "/", "size", "desc")
	resp := decodeBrowse(t, rr)

	names := trustEntryNames(resp)
	if len(names) < 2 {
		t.Fatalf("expected at least two entries, got %v", names)
	}
	if !resp.Entries[0].IsDir {
		t.Errorf("expected folder first, got %s", names[0])
	}
	if resp.Entries[1].Name != "large.txt" {
		t.Errorf("expected largest file first after folders, got %s", names[1])
	}
}

func TestTrust_SortByNameAsc(t *testing.T) {
	root := setupTestDir(t)
	trustCreateFile(t, root, "banana.txt")
	trustCreateFile(t, root, "apple.txt")

	mux := newMux(testConfig(root))
	rr := trustBrowseRequest(t, mux, "/", "name", "asc")
	resp := decodeBrowse(t, rr)

	names := trustEntryNames(resp)
	if len(names) < 2 {
		t.Fatalf("expected at least two entries, got %v", names)
	}
	if names[0] != "apple.txt" {
		t.Errorf("expected apple.txt first, got %s", names[0])
	}
	if names[1] != "banana.txt" {
		t.Errorf("expected banana.txt second, got %s", names[1])
	}
}

