	"testing"
	"time"
)

func trustFileEntry(name string, isDir bool, size int64, modTime time.Time) FileEntry {
	return FileEntry{Name: name, IsDir: isDir, Size: size, ModTime: modTime}
}

func trustSortEntries(files []FileEntry, by string, desc bool) []FileEntry {
	sortEntries(files, by, desc)
	return files
}

func trustNames(files []FileEntry) []string {
	names := make([]string, len(files))
	for i, f := range files {
		names[i] = f.Name
	}
	return names
}

func TestTrust_SortByNameAscending(t *testing.T) {
	files := []FileEntry{
		trustFileEntry("b.txt", false, 100, time.Now()),
		trustFileEntry("a.txt", false, 200, time.Now()),
		trustFileEntry("c.txt", false, 50, time.Now()),
	}
	got := trustNames(trustSortEntries(files, "name", false))
	want := []string{"a.txt", "b.txt", "c.txt"}
	for i := range want {
		if got[i] != want[i] {
			t.Errorf("expected %q at index %d, got %q", want[i], i, got[i])
		}
	}
}

