func TestTrust_SortBySizeAscending(t *testing.T) {
	files := []FileEntry{
		trustFileEntry("big.txt", false, 1000, time.Now()),
		trustFileEntry("small.txt", false, 10, time.Now()),
		trustFileEntry("medium.txt", false, 100, time.Now()),
	}
	got := trustNames(trustSortEntries(files, "size", false))
	want := []string{"small.txt", "medium.txt", "big.txt"}
